export type IconName = keyof typeof iconPaths

const iconVariants = cva('inline-block shrink-0 transition-colors', {
  variants: {
    size: {
      default: 'w-[16px] h-[16px]',
    },
    variant: {
      stroke: 'stroke-current fill-none stroke-[1.5]',
      fill: 'fill-current stroke-none',
    },
  },
  defaultVariants: {
    size: 'default',
    variant: 'stroke',
  },
})

interface IconProps extends React.SVGProps<SVGSVGElement>, VariantProps<typeof iconVariants> {
  name: IconName
}

export const Icon = ({ className, size, variant, name, ...props }: IconProps) => {
  const IconPath = iconPaths[name]

  if (!IconPath) {
    console.warn(`Icon "${name}" chưa được định nghĩa!`)
    return null
  }

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 16 16"
      className={cn(iconVariants({ size, variant, className }))}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      {IconPath}
    </svg>
  )
}
